index 0000000..8f96eb9
--- /dev/null
+++ b/specs/4/SPEC.md
@@ -0,0 +1,32 @@
+# Issue 4: Member search shows other members' phone numbers
+
+## Outcome
+
+Desk member search shows who a member is, not how to contact them. Anyone queueing at the desk
+cannot read a phone number or email from the search results.
+
+## Requirements
+
+- When a desk volunteer searches members by name, the system shall return no phone number for any match.
+- When a desk volunteer searches members by name, the system shall return no email address for any match.
+- When a desk volunteer searches members by name, the system shall still return each match's id and name.
+- The system shall keep finding members by part of their name, ordered by name.
+
+## Must not change
+
+- Which members a name search matches, and their order.
+- `src/auth/` (protected).
+- Money handling (integer cents) and every other desk action.
+- The full member record elsewhere, such as the loan and borrow flows.
+
+## Out of scope
+
+- Hiding contact details anywhere other than member search results.
+- Changing who may see contact details (roles, permissions).
+- Changes to the database schema or seed data.
+
+## Done when
+
+- The new tests in `tests/members/search.test.ts` pass.
+- The existing tests still pass.
+- `bun run gate` exits 0.
diff --git a/src/members/search.ts b/src/members/search.ts
index 0c6e937..1f314cd 100644
--- a/src/members/search.ts
+++ b/src/members/search.ts
@@ -1,9 +1,10 @@
 import type { Database } from "bun:sqlite";
-import { type Member, toMember } from "../db";
+
+export type MemberSearchResult = { id: string; name: string };

 // Desk volunteers find a member by part of their name.
-export function searchMembers(db: Database, namePart: string): Member[] {
-  const query = db.query("SELECT * FROM members WHERE name LIKE ? ORDER BY name");
-  const rows = query.all(`%${namePart}%`) as Record<string, unknown>[];
-  return rows.map(toMember);
+// Results show who a member is, never how to contact them.
+export function searchMembers(db: Database, namePart: string): MemberSearchResult[] {
+  const query = db.query("SELECT id, name FROM members WHERE name LIKE ? ORDER BY name");
+  return query.all(`%${namePart}%`) as MemberSearchResult[];
 }
diff --git a/tests/members/search.test.ts b/tests/members/search.test.ts
index 1dfd4d0..99cd965 100644
--- a/tests/members/search.test.ts
+++ b/tests/members/search.test.ts
@@ -7,3 +7,34 @@ test("search finds a member by part of their name", () => {
   const found = searchMembers(db, "Oka");
   expect(found.map((member) => member.name)).toEqual(["Ada Okafor"]);
 });
+
+test("search results carry no phone number", () => {
+  const db = seed(":memory:");
+  const found = searchMembers(db, "Ha");
+  expect(found.length).toBeGreaterThan(0);
+  for (const member of found) {
+    expect(member).not.toHaveProperty("phone");
+  }
+});
+
+test("search results carry no email address", () => {
+  const db = seed(":memory:");
+  const found = searchMembers(db, "Ha");
+  expect(found.length).toBeGreaterThan(0);
+  for (const member of found) {
+    expect(member).not.toHaveProperty("email");
+  }
+});
+
+test("search results still carry id and name", () => {
+  const db = seed(":memory:");
+  const found = searchMembers(db, "Oka");
+  expect(found[0]).toHaveProperty("id");
+  expect(found[0]).toHaveProperty("name", "Ada Okafor");
+});
+
+test("search results stay ordered by name", () => {
+  const db = seed(":memory:");
+  const names = searchMembers(db, "a").map((member) => member.name);
+  expect(names).toEqual([...names].sort());
+});

